@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<div class="container mt-4">
    <h2 class="mb-4">🔍 Track Your Shipment</h2>

    <div class="row mb-4">
        <div class="col-md-6">
            <div class="input-group">
                <input type="text" class="form-control form-control-lg" placeholder="Enter tracking number (e.g. SHP-20260601-A1B2C3D4)"
                       @bind="trackingNumber" @bind:event="oninput"
                       @onkeydown="OnKeyDown" />
                <button class="btn btn-primary btn-lg" @onclick="SearchShipment" disabled="@isSearching">
                    @(isSearching ? "Searching..." : "Track")
                </button>
            </div>
        </div>
    </div>

    @if (searched && shipment is null)
    {
        <div class="alert alert-warning">
            <strong>Not found.</strong> No shipment matches tracking number <code>@searchedNumber</code>. Please check the number and try again.
        </div>
    }

    @if (shipment is not null)
    {
        <div class="card shadow-sm">
            <div class="card-header bg-dark text-white d-flex justify-content-between">
                <span><strong>Tracking:</strong> @shipment.TrackingNumber</span>
                <span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@FormatStatus(shipment.Status)</span>
            </div>
            <div class="card-body">
                <div class="row g-4">
                    <div class="col-md-6">
                        <h5>Shipment Details</h5>
                        <table class="table table-borderless">
                            <tr><th>Description</th><td>@shipment.Description</td></tr>
                            <tr><th>Origin</th><td>@shipment.Origin</td></tr>
                            <tr><th>Destination</th><td>@shipment.Destination</td></tr>
                            <tr><th>Created</th><td>@shipment.CreatedAt.ToString("MMM dd, yyyy h:mm tt") UTC</td></tr>
                        </table>
                    </div>
                    <div class="col-md-6">
                        <h5>Delivery Information</h5>
                        @if (shipment.EstimatedDelivery.HasValue)
                        {
                            <div class="alert @GetDeliveryAlertClass()">
                                <strong>Estimated Delivery:</strong><br />
                                <span class="fs-4">@shipment.EstimatedDelivery.Value.ToString("dddd, MMMM dd, yyyy")</span>
                                @if (shipment.Status == ShipmentStatus.Delivered)
                                {
                                    <br /><span class="text-success fw-bold">✅ Delivered</span>
                                }
                                else if (shipment.Status == ShipmentStatus.Cancelled)
                                {
                                    <br /><span class="text-danger fw-bold">❌ Cancelled</span>
                                }
                                else
                                {
                                    var daysLeft = (shipment.EstimatedDelivery.Value.Date - DateTime.UtcNow.Date).Days;
                                    <br />
                                    @if (daysLeft > 0)
                                    {
                                        <span>@daysLeft day(s) remaining</span>
                                    }
                                    else if (daysLeft == 0)
                                    {
                                        <span class="fw-bold">Arriving today!</span>
                                    }
                                    else
                                    {
                                        <span class="text-warning">Delivery is @Math.Abs(daysLeft) day(s) overdue</span>
                                    }
                                }
                            </div>
                        }
                        else
                        {
                            <div class="alert alert-secondary">
                                Estimated delivery date not yet available.
                            </div>
                        }
                    </div>
                </div>

                <h5 class="mt-3">Shipment Progress</h5>
                <div class="progress" style="height: 30px;">
                    <div class="progress-bar @GetProgressBarClass()" role="progressbar"
                         style="width: @GetProgressPercent()%"
                         aria-valuenow="@GetProgressPercent()" aria-valuemin="0" aria-valuemax="100">
                        @FormatStatus(shipment.Status)
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private string trackingNumber = string.Empty;
    private string searchedNumber = string.Empty;
    private Shipment? shipment;
    private bool searched;
    private bool isSearching;

    private async Task OnKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await SearchShipment();
    }

    private async Task SearchShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber))
            return;

        isSearching = true;
        searched = false;
        shipment = null;
        try
        {
            searchedNumber = trackingNumber.Trim();
            shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(searchedNumber);
            searched = true;
        }
        finally
        {
            isSearching = false;
        }
    }

    private int GetProgressPercent() => shipment?.Status switch
    {
        ShipmentStatus.Pending => 10,
        ShipmentStatus.PickedUp => 30,
        ShipmentStatus.InTransit => 55,
        ShipmentStatus.OutForDelivery => 80,
        ShipmentStatus.Delivered => 100,
        ShipmentStatus.Cancelled => 100,
        _ => 0
    };

    private string GetProgressBarClass() => shipment?.Status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-primary progress-bar-striped progress-bar-animated"
    };

    private string GetDeliveryAlertClass() => shipment?.Status switch
    {
        ShipmentStatus.Delivered => "alert-success",
        ShipmentStatus.Cancelled => "alert-danger",
        _ => "alert-info"
    };

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };

    private static string FormatStatus(ShipmentStatus status) => status switch
    {
        ShipmentStatus.InTransit => "In Transit",
        ShipmentStatus.OutForDelivery => "Out for Delivery",
        ShipmentStatus.PickedUp => "Picked Up",
        _ => status.ToString()
    };
}

