@page "/shipments"
@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Dispatcher Dashboard</PageTitle>

<div class="container-fluid mt-3">
    <div class="d-flex justify-content-between align-items-center mb-3">
        <h2>🚛 Dispatcher Dashboard</h2>
        <button class="btn btn-success" @onclick="ShowCreateForm">
            ➕ New Shipment
        </button>
    </div>

    @if (showCreateForm)
    {
        <div class="card mb-4">
            <div class="card-header">Create New Shipment</div>
            <div class="card-body">
                <EditForm Model="newShipment" OnValidSubmit="CreateShipment" FormName="CreateShipment">
                    <DataAnnotationsValidator />
                    <div class="row g-3">
                        <div class="col-md-4">
                            <label class="form-label">Origin</label>
                            <InputText class="form-control" @bind-Value="newShipment.Origin" placeholder="e.g. New York, NY" />
                        </div>
                        <div class="col-md-4">
                            <label class="form-label">Destination</label>
                            <InputText class="form-control" @bind-Value="newShipment.Destination" placeholder="e.g. Los Angeles, CA" />
                        </div>
                        <div class="col-md-4">
                            <label class="form-label">Customer Email</label>
                            <InputText class="form-control" @bind-Value="newShipment.CustomerEmail" type="email" />
                        </div>
                        <div class="col-md-6">
                            <label class="form-label">Description</label>
                            <InputText class="form-control" @bind-Value="newShipment.Description" placeholder="Package description" />
                        </div>
                        <div class="col-md-3">
                            <label class="form-label">Estimated Delivery</label>
                            <InputDate class="form-control" @bind-Value="newShipment.EstimatedDelivery" />
                        </div>
                        <div class="col-md-3 d-flex align-items-end gap-2">
                            <button type="submit" class="btn btn-primary" disabled="@isSubmitting">
                                @(isSubmitting ? "Creating..." : "Create")
                            </button>
                            <button type="button" class="btn btn-secondary" @onclick="CancelCreate">Cancel</button>
                        </div>
                    </div>
                </EditForm>
            </div>
        </div>
    }

    <div class="row mb-3">
        <div class="col-auto">
            <label class="form-label fw-bold">Filter by Status:</label>
        </div>
        <div class="col-auto">
            <select class="form-select" @onchange="OnStatusFilterChanged">
                <option value="">All</option>
                @foreach (var status in Enum.GetValues<ShipmentStatus>())
                {
                    <option value="@status" selected="@(statusFilter == status)">@FormatStatus(status)</option>
                }
            </select>
        </div>
    </div>

    @if (shipments is null)
    {
        <div class="text-center py-5">
            <div class="spinner-border text-primary" role="status"></div>
            <p class="mt-2 text-muted">Loading shipments...</p>
        </div>
    }
    else if (shipments.Count == 0)
    {
        <div class="alert alert-info">No shipments found.</div>
    }
    else
    {
        <div class="table-responsive">
            <table class="table table-striped table-hover">
                <thead class="table-dark">
                    <tr>
                        <th>Tracking #</th>
                        <th>Origin</th>
                        <th>Destination</th>
                        <th>Status</th>
                        <th>Customer</th>
                        <th>Est. Delivery</th>
                        <th>Actions</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var shipment in shipments)
                    {
                        <tr>
                            <td><code>@shipment.TrackingNumber</code></td>
                            <td>@shipment.Origin</td>
                            <td>@shipment.Destination</td>
                            <td>
                                <span class="badge @GetStatusBadgeClass(shipment.Status)">
                                    @FormatStatus(shipment.Status)
                                </span>
                            </td>
                            <td>@shipment.CustomerEmail</td>
                            <td>@shipment.EstimatedDelivery?.ToString("MMM dd, yyyy")</td>
                            <td>
                                @if (shipment.Status != ShipmentStatus.Delivered && shipment.Status != ShipmentStatus.Cancelled)
                                {
                                    <select class="form-select form-select-sm" style="width: auto; display: inline-block;"
                                            @onchange="e => UpdateStatus(shipment.Id, e)">
                                        <option value="" disabled selected>Update...</option>
                                        @foreach (var status in GetNextStatuses(shipment.Status))
                                        {
                                            <option value="@status">@FormatStatus(status)</option>
                                        }
                                    </select>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
    }
</div>

@code {
    private List<Shipment>? shipments;
    private ShipmentStatus? statusFilter;
    private bool showCreateForm;
    private bool isSubmitting;
    private Shipment newShipment = new();

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        shipments = await ShipmentService.GetShipmentsByStatusAsync(statusFilter);
    }

    private async Task OnStatusFilterChanged(ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var status))
            statusFilter = status;
        else
            statusFilter = null;
        await LoadShipments();
    }

    private void ShowCreateForm() => showCreateForm = true;
    private void CancelCreate()
    {
        showCreateForm = false;
        newShipment = new();
    }

    private async Task CreateShipment()
    {
        isSubmitting = true;
        try
        {
            await ShipmentService.CreateShipmentAsync(newShipment);
            showCreateForm = false;
            newShipment = new();
            await LoadShipments();
        }
        finally
        {
            isSubmitting = false;
        }
    }

    private async Task UpdateStatus(int id, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            await ShipmentService.UpdateShipmentStatusAsync(id, newStatus);
            await LoadShipments();
        }
    }

    private static List<ShipmentStatus> GetNextStatuses(ShipmentStatus current) => current switch
    {
        ShipmentStatus.Pending => [ShipmentStatus.PickedUp, ShipmentStatus.Cancelled],
        ShipmentStatus.PickedUp => [ShipmentStatus.InTransit, ShipmentStatus.Cancelled],
        ShipmentStatus.InTransit => [ShipmentStatus.OutForDelivery, ShipmentStatus.Cancelled],
        ShipmentStatus.OutForDelivery => [ShipmentStatus.Delivered],
        _ => []
    };

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };

    private static string FormatStatus(ShipmentStatus status) => status switch
    {
        ShipmentStatus.InTransit => "In Transit",
        ShipmentStatus.OutForDelivery => "Out for Delivery",
        ShipmentStatus.PickedUp => "Picked Up",
        _ => status.ToString()
    };
}

@page "/track"
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<div class="container mt-4">
    <h2 class="mb-4">🔍 Track Your Shipment</h2>

    <div class="row mb-4">
        <div class="col-md-6">
            <div class="input-group">
                <input type="text" class="form-control form-control-lg" placeholder="Enter tracking number (e.g. SHP-20260601-A1B2C3D4)"
                       @bind="trackingNumber" @bind:event="oninput"
                       @onkeydown="OnKeyDown" />
                <button class="btn btn-primary btn-lg" @onclick="SearchShipment" disabled="@isSearching">
                    @(isSearching ? "Searching..." : "Track")
                </button>
            </div>
        </div>
    </div>

    @if (searched && shipment is null)
    {
        <div class="alert alert-warning">
            <strong>Not found.</strong> No shipment matches tracking number <code>@searchedNumber</code>. Please check the number and try again.
        </div>
    }

    @if (shipment is not null)
    {
        <div class="card shadow-sm">
            <div class="card-header bg-dark text-white d-flex justify-content-between">
                <span><strong>Tracking:</strong> @shipment.TrackingNumber</span>
                <span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@FormatStatus(shipment.Status)</span>
            </div>
            <div class="card-body">
                <div class="row g-4">
                    <div class="col-md-6">
                        <h5>Shipment Details</h5>
                        <table class="table table-borderless">
                            <tr><th>Description</th><td>@shipment.Description</td></tr>
                            <tr><th>Origin</th><td>@shipment.Origin</td></tr>
                            <tr><th>Destination</th><td>@shipment.Destination</td></tr>
                            <tr><th>Created</th><td>@shipment.CreatedAt.ToString("MMM dd, yyyy h:mm tt") UTC</td></tr>
                        </table>
                    </div>
                    <div class="col-md-6">
                        <h5>Delivery Information</h5>
                        @if (shipment.EstimatedDelivery.HasValue)
                        {
                            <div class="alert @GetDeliveryAlertClass()">
                                <strong>Estimated Delivery:</strong><br />
                                <span class="fs-4">@shipment.EstimatedDelivery.Value.ToString("dddd, MMMM dd, yyyy")</span>
                                @if (shipment.Status == ShipmentStatus.Delivered)
                                {
                                    <br /><span class="text-success fw-bold">✅ Delivered</span>
                                }
                                else if (shipment.Status == ShipmentStatus.Cancelled)
                                {
                                    <br /><span class="text-danger fw-bold">❌ Cancelled</span>
                                }
                                else
                                {
                                    var daysLeft = (shipment.EstimatedDelivery.Value.Date - DateTime.UtcNow.Date).Days;
                                    <br />
                                    @if (daysLeft > 0)
                                    {
                                        <span>@daysLeft day(s) remaining</span>
                                    }
                                    else if (daysLeft == 0)
                                    {
                                        <span class="fw-bold">Arriving today!</span>
                                    }
                                    else
                                    {
                                        <span class="text-warning">Delivery is @Math.Abs(daysLeft) day(s) overdue</span>
                                    }
                                }
                            </div>
                        }
                        else
                        {
                            <div class="alert alert-secondary">
                                Estimated delivery date not yet available.
                            </div>
                        }
                    </div>
                </div>

                <h5 class="mt-3">Shipment Progress</h5>
                <div class="progress" style="height: 30px;">
                    <div class="progress-bar @GetProgressBarClass()" role="progressbar"
                         style="width: @GetProgressPercent()%"
                         aria-valuenow="@GetProgressPercent()" aria-valuemin="0" aria-valuemax="100">
                        @FormatStatus(shipment.Status)
                    </div>
                </div>
            </div>
        </div>
    }
</div>

